function Brand() {
  return <div className="flex items-center gap-3"><div className="grid size-10 shrink-0 place-items-center rounded-[13px] bg-[#4f6df5] shadow-[0_8px_20px_rgba(79,109,245,.28)]"><ShieldCheck className="size-5 text-white" /></div><div><p className="text-[19px] font-semibold leading-5 tracking-[-.03em]">Truvault</p><p className="mt-1 text-[9px] font-semibold tracking-[.18em] text-slate-400">IDENTITY NETWORK</p></div></div>;
}

function Status({ children, tone = 'green' }: { children: React.ReactNode; tone?: Tone }) {
  const styles: Record<Tone, string> = {
    green: 'bg-emerald-50 text-emerald-700 ring-emerald-600/15',
    yellow: 'bg-amber-50 text-amber-700 ring-amber-600/15',
    red: 'bg-red-50 text-red-700 ring-red-600/15',
    blue: 'bg-indigo-50 text-indigo-700 ring-indigo-600/15',
    gray: 'bg-slate-100 text-slate-600 ring-slate-600/10',
  };
  return <span className={`inline-flex w-fit items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-semibold ring-1 ${styles[tone]}`}>{children}</span>;
}

function SectionHead({ eyebrow, title, subtitle, action }: { eyebrow?: string; title: string; subtitle: string; action?: React.ReactNode }) {
  return <div className="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div>{eyebrow && <p className="mb-2 text-[10px] font-bold uppercase tracking-[.18em] text-[#6375cf]">{eyebrow}</p>}<h2 className="text-2xl font-semibold tracking-[-.035em] text-[#17213b] sm:text-[28px]">{title}</h2><p className="mt-1.5 max-w-2xl text-sm leading-6 text-[#707a8f]">{subtitle}</p></div>{action}</div>;
}

function Panel({ children, className = '' }: { children: React.ReactNode; className?: string }) {
  return <div className={`rounded-2xl border border-[#e3e8f2] bg-white shadow-[0_1px_2px_rgba(16,24,40,.02)] ${className}`}>{children}</div>;
}

function Metric({ label, value, icon: Icon, trend, tone = 'blue' }: { label: string; value: string; icon: typeof Activity; trend: string; tone?: Tone }) {
  const boxes: Record<Tone, string> = { green: 'bg-emerald-50 text-emerald-700', yellow: 'bg-amber-50 text-amber-700', red: 'bg-red-50 text-red-700', blue: 'bg-indigo-50 text-indigo-700', gray: 'bg-slate-100 text-slate-600' };
  return <Panel className="p-5"><div className="flex items-center justify-between"><div className={`grid size-10 place-items-center rounded-xl ${boxes[tone]}`}><Icon className="size-[18px]" /></div><span className="text-[11px] text-[#8a93a5]">{trend}</span></div><p className="mt-5 text-[26px] font-semibold tracking-[-.04em] text-[#17213b]">{value}</p><p className="mt-1 text-xs font-medium text-[#758095]">{label}</p></Panel>;
}

function EmptyModal({ children, onClose, width = 'max-w-xl' }: { children: React.ReactNode; onClose: () => void; width?: string }) {
  return <div className="fixed inset-0 z-50 grid place-items-end bg-[#071129]/45 p-0 backdrop-blur-[3px] sm:place-items-center sm:p-5" onMouseDown={onClose}><div role="dialog" aria-modal="true" className={`max-h-[94vh] w-full overflow-y-auto rounded-t-[24px] bg-white shadow-2xl sm:rounded-[24px] ${width}`} onMouseDown={(e) => e.stopPropagation()}>{children}</div></div>;
}

