  return <><SectionHead eyebrow="Secure digital assets" title="Documents & credentials" subtitle="Every asset is encrypted, content-addressed on IPFS and anchored to Polygon." action={<Button onClick={onUpload} className="h-10 rounded-xl bg-[#3f5eea] px-4 text-white"><UploadCloud /> Upload document</Button>} /><div className="mb-5 grid gap-4 sm:grid-cols-3"><Metric label="Verified assets" value="6" icon={FileCheck2} trend="All current" tone="green" /><Metric label="Blockchain proofs" value="6" icon={Network} trend="100% anchored" /><Metric label="Shared assets" value="2" icon={Users} trend="Time-bound" tone="yellow" /></div><Panel><div className="flex flex-col gap-3 border-b border-[#e8ecf3] p-5 sm:flex-row sm:items-center sm:justify-between"><div><h3 className="font-semibold">Your assets</h3><p className="mt-1 text-xs text-[#8a93a5]">Synthetic demonstration data</p></div><div className="flex items-center gap-2 rounded-xl border border-[#e0e5ee] bg-white px-3 py-2 text-xs text-[#8a93a5]"><Search className="size-4" /> Search credentials</div></div><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left"><thead><tr className="border-b border-[#edf0f5] bg-[#fafbfc] text-[10px] uppercase tracking-wider text-[#8d96a7]"><th className="px-5 py-3.5 font-semibold">Asset</th><th className="px-5 py-3.5 font-semibold">Issuer</th><th className="px-5 py-3.5 font-semibold">Integrity</th><th className="px-5 py-3.5 font-semibold">Stored</th><th className="px-5 py-3.5 font-semibold">Status</th><th className="px-5 py-3.5" /></tr></thead><tbody>{documents.map((doc) => <tr key={doc.name} className="border-b border-[#edf0f5] last:border-0"><td className="px-5 py-4"><div className="flex items-center gap-3"><div className="grid size-9 place-items-center rounded-lg bg-[#eef1ff] text-[#4861d5]"><doc.icon className="size-4" /></div><div><p className="text-sm font-semibold">{doc.name}</p><p className="mt-1 text-[11px] text-[#8a93a5]">{doc.type}</p></div></div></td><td className="px-5 py-4 text-xs text-[#5f6a7f]">{doc.issuer}</td><td className="px-5 py-4 font-mono text-[11px] text-[#68748a]">SHA-256</td><td className="px-5 py-4 text-xs text-[#5f6a7f]">IPFS</td><td className="px-5 py-4"><Status tone={doc.status === 'Verified' ? 'green' : 'yellow'}>{doc.status}</Status></td><td className="px-5 py-4"><button onClick={onProof} className="text-xs font-semibold text-[#3f5eea]">View proof</button></td></tr>)}</tbody></table></div></Panel></>;
